(* [comment removed for export] *)
Definition chx_exitA_stmt (pc e loc : Z) : Prop :=
  forall rax ra sp gp tp t1 t2 t3 s0v s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t4 t5 t6 q0 q1 q2 q3 q4 q5 q6 q7 q8
    (F : bvmap 5 word) fc (m m1 : mem) (it0 I E lo : Z) (bs : list byte) (itv : Z) (E0 : ecv) (g : bool) (j8 junk : list byte),
  chx_ctx m m1 sp s0v ra it0 I E lo bs itv E0 g j8 [CB 24 junk] -> chx_pure sp it0 I E lo bs E0 ->
  it0 <= itv <= it0 + Z.of_nat (length bs) ->
  evt rsegs (chx_post ra sp gp tp s0v s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc it0 I E lo bs E0 m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -48)) gp tp q0 t1 t2 (wz E) s1 q1 q2 q3 q4 q5 q6 q7 q8
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m1 (seg_rom rsegs)).

Local Ltac chx_exitA_script e loc :=
  intros rax ra sp gp tp t1 t2 t3 s0v s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t4 t5 t6 q0 q1 q2 q3 q4 q5 q6 q7 q8 F fc m m1 it0 I E lo bs itv E0 g j8 junk;
  intros CTX PURE ITV;
  destruct CTX as (FR0 & TMP & FRhi & IT & EC & HC & XS & ST & WIN & MU & WM & MI);
  destruct PURE as (EOK & LO & IMG & QLO & QHI & ILO & IHI & ELO & EHI & DIE);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  unfold ErrCodeCells in EC; unfold chx_W, G_HTTP_CAT in *; unfold chx_regs, wz in *;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  (* [comment removed for export] *)
  step; step; step; step;
  call_assignA_with (bv_unsigned sp + -48) (bv_unsigned sp + -40) e lo g junk;
  clear HC XS;
  lazymatch goal with
  | TMP' : rw_cells _ _ (bv_unsigned sp + -40) (ErrCodeCells _), HC' : HttpCat _ true, XS' : XStatics _, ST' : stk _ _ lo _ |- _ =>
    concretize_ec TMP';
    steps_to 0x3c504%Z;
    expose_statics HC' XS' [(lo, bv_unsigned sp); (E, E + 24)]%Z;
    (* [comment removed for export] *)
    step; step; st1; st1; st1;
    (* [comment removed for export] *)
    step; step;
    join_frame TMP' FRhi (bv_unsigned sp + -40); join_frame FR0 TMP' (bv_unsigned sp + -48);
    step; release_frame FR0 ST' (bv_unsigned sp); step;
    lazymatch goal with
    | MU2 : munch [(lo, bv_unsigned sp); (E, E + 24)]%Z ?mx _, WM2 : wmono _ ?mx _ |- _ =>
        chx_finish itv (EC_http_loc e loc) true;
        [ right; unfold EC_http_loc, ec_make_loc, ec_ok, HE_NEED_MORE, HE_BAD_CHUNK_EXTENSION, G_HTTP_CAT;
          cbn [ec_val ec_cat ec_flags Z.eqb]; repeat split; try lia; reflexivity
        | close_HttpCat_chunks
        | close_XStatics XS' MU2 WM2 ]
    end
  end.
