(* [comment removed for export] *)
Lemma win_byte : forall m it0 bs p, bytes_at rsegs m it0 bs -> it0 <= p < it0 + Z.of_nat (length bs) ->
  exists b, nth_error bs (Z.to_nat (p - it0)) = Some b.
Proof.
  intros m it0 bs p WIN Hp. destruct (nth_error bs (Z.to_nat (p - it0))) as [b|] eqn:N; [exists b; reflexivity|].
  apply nth_error_None in N. lia.
Qed.

(* [comment removed for export] *)
Definition TABB_TCHAR : list byte := map (fun z => Z_to_bv 8 z) TAB_IS_TOKEN_CHAR.
Definition TABB_QD : list byte := map (fun z => Z_to_bv 8 z) TAB_IS_QDCHAR.
Definition TABB_QP : list byte := map (fun z => Z_to_bv 8 z) TAB_IS_QPCHAR.

