Lemma tab_byte : forall (T : list Z) c, length T = 256%nat -> 0 <= c < 256 ->
  nth_error (map (fun z => Z_to_bv 8 z) T) (Z.to_nat c) = Some (Z_to_bv 8 (nth (Z.to_nat c) T 0)).
Proof.
  intros T c LT Hc. rewrite nth_error_map.
  destruct (nth_error T (Z.to_nat c)) as [v|] eqn:N.
  - cbn. f_equal. f_equal. symmetry. apply nth_error_nth. exact N.
  - apply nth_error_None in N. lia.
Qed.
Lemma len_TCHAR : length TAB_IS_TOKEN_CHAR = 256%nat. Proof. reflexivity. Qed.
Lemma len_QD : length TAB_IS_QDCHAR = 256%nat. Proof. reflexivity. Qed.
Lemma len_QP : length TAB_IS_QPCHAR = 256%nat. Proof. reflexivity. Qed.

(* [comment removed for export] *)
Definition cut_pc (c : nat) : Z :=
  match c with 0%nat => 0x3c2c8 | 1%nat => 0x3c2dc | 2%nat => 0x3c2f8 | 3%nat => 0x3c308 | 4%nat => 0x3c334
             | 5%nat => 0x3c358 | 6%nat => 0x3c39c | 7%nat => 0x3c3c4 | _ => 0x3c424 end.
Definition cut_rank (c : nat) : Z :=
  match c with 0%nat => 3 | 1%nat => 1 | 2%nat => 0 | 3%nat => 0 | 4%nat => 2 | 5%nat => 2 | 6%nat => 0 | 7%nat => 0 | _ => 4 end.
(* [comment removed for export] *)
Definition cut_t1 (c : nat) (p : Z) : Z := match c with 3%nat | 6%nat => p + 1 | _ => p end.
Definition cut_t2 (c : nat) (p : Z) (x : Z) : Z := match c with 3%nat | 6%nat => p | 7%nat => p - 1 | _ => x end.
(* [comment removed for export] *)
Definition cut_known (c : nat) : bool := match c with 0%nat | 1%nat | 2%nat | 3%nat | 6%nat => true | _ => false end.

Definition cut_side (c : nat) (p itv it0 L : Z) : Prop :=
  it0 <= p /\ (if cut_known c then itv = p /\ p < L else p <= L) /\ (c = 7%nat -> it0 + 1 <= p).

(* [comment removed for export] *)
Definition CUT_AT (c : nat) (B : Z) : Prop :=
  forall (p x : Z) rax ra sp gp tp t3 s0v s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (it0 I E lo : Z) (bs : list byte) (itv : Z) (E0 : ecv) (g : bool) (j8 junk : list byte),
  chx_ctx m m1 sp s0v ra it0 I E lo bs itv E0 g j8 [CB 24 junk] -> chx_pure sp it0 I E lo bs E0 ->
  cut_side c p itv it0 (it0 + Z.of_nat (length bs)) ->
  8 * (it0 + Z.of_nat (length bs) - p) + cut_rank c < B ->
  evt rsegs (chx_post ra sp gp tp s0v s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc it0 I E lo bs E0 m)
    (MS (chx_regs rax (Z_to_bv 64 (bv_unsigned sp + -48)) gp tp (wz (cut_t1 c p)) (wz (cut_t2 c p x)) t3
                  I (it0 + Z.of_nat (length bs)) E s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t4 t5 t6)
        F (Z_to_bv 64 (cut_pc c)) fc None m1 (seg_rom rsegs)).

Definition CUTS (B : Z) : Prop := forall c, (c <= 8)%nat -> CUT_AT c B.

(* [comment removed for export] *)
Local Ltac cut_open :=
  intros p x rax ra sp gp tp t3 s0v s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t4 t5 t6 F fc m m1 it0 I E lo bs itv E0 g j8 junk;
  intros CTX PURE SIDE MEAS;
  pose proof CTX as CTX'; pose proof PURE as PURE';
  destruct CTX' as (FR0 & TMP & FRhi & IT & EC & HC & XS & ST & WIN & MU & WM & MI);
  destruct PURE' as (EOK & LO & IMG & QLO & QHI & ILO & IHI & ELO & EHI & DIE);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  unfold ErrCodeCells in EC; unfold chx_W, G_HTTP_CAT in *; unfold chx_regs in *;
  unfold cut_t1, cut_t2, cut_pc, cut_side, cut_known in SIDE |- *; unfold cut_rank in MEAS;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  unfold wz.

(* [comment removed for export] *)
Local Ltac win_load q :=
  lazymatch goal with WIN : bytes_at _ ?mx ?it0 ?bs |- _ =>
    let b := fresh "b" in let N := fresh "N" in let RD := fresh "RD" in let BR := fresh "BR" in
    destruct (win_byte _ _ _ q WIN ltac:(lia)) as [b N];
    pose proof (zb_range b) as BR; unfold zb in BR;
    pose proof (u8ro_read rsegs _ it0 bs (q - it0) b (Z_to_bv 64 q) WIN N ltac:(lia) ltac:(symmetry; apply wa_of_Z_to_bv; lia)) as RD;
    step; clear RD; change (zxb b) with (Z_to_bv 64 (zb b)); fold (zb b) in BR
  end.

(* [comment removed for export] *)
Local Ltac to_cut IH c q xv CTX PURE :=
  eapply (IH c ltac:(lia) q xv);
  [ exact CTX | exact PURE
  | unfold cut_side, cut_known; repeat split; try lia; try (intros; lia)
  | unfold cut_rank; lia ].
Scheme kc__3 := Elimination for Corelib.Init.Datatypes.bool Sort Prop.

