(* [comment removed for export] *)
Local Ltac store_it HC XS :=
  lazymatch type of XS with XStatics ?mx =>
    lazymatch goal with IT : rw_cells _ mx ?I [C8 _] |- _ =>
      let MU2 := fresh "MUi" in let WM2 := fresh "WMi" in let HC' := fresh "HC" in let XS' := fresh "XS" in
      pose proof (munch_refl [(I, I + 8)]%Z mx) as MU2; pose proof (wmono_refl rsegs mx) as WM2;
      st1;
      pose proof (HttpCat_transport _ _ _ _ HC MU2 WM2 ltac:(unfold G_HTTP_CAT; cbn; lia) ltac:(unfold G_HTTP_CAT_GUARD; cbn; lia)) as HC';
      pose proof (XStatics_transport _ _ _ XS MU2 WM2 ltac:(repeat constructor; cbn; lia)) as XS';
      clear HC XS MU2 WM2; rename HC' into HC; rename XS' into XS
    end
  end.

(* [comment removed for export] *)
Local Ltac rebuild_ctx CTX :=
  clear CTX;
  lazymatch goal with
  | FR0 : rw_cells _ ?mx (bv_unsigned ?sp + -48) [CB 8 ?j8], IT : rw_cells _ _ ?I [C8 (Z_to_bv 64 ?itv)],
    XS : XStatics _, HC : HttpCat _ ?g, MU : munch _ ?m0 _ |- _ =>
      lazymatch goal with |- evt _ (chx_post _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ ?it0 _ ?E ?lo ?bs ?E0 _) _ =>
        lazymatch goal with TMP : rw_cells _ mx (bv_unsigned sp + -40) [CB 24 ?junk],
                            FRhi : rw_cells _ mx (bv_unsigned sp + -16) [C8 ?s0v; C8 ?rav] |- _ =>
          assert (CTX : chx_ctx m0 mx sp s0v rav it0 I E lo bs itv E0 g j8 [CB 24 junk])
            by (repeat (split; [eassumption|]); eassumption)
        end
      end
  end.

