(* [comment removed for export] *)
Local Ltac tab_load TBL TABB TAB LEN c base :=
  let TB := fresh "TB" in let RD := fresh "RD" in
  lazymatch goal with MI : mem_inv _ ?mx |- _ =>
    pose proof (TBL mx MI) as TB;
    pose proof (u8ro_read rsegs mx base TABB c (Z_to_bv 8 (nth (Z.to_nat c) TAB 0)) (Z_to_bv 64 (base + c)) TB
                 (tab_byte TAB c LEN ltac:(lia)) ltac:(lia) ltac:(symmetry; apply wa_of_Z_to_bv; lia)) as RD;
    step; clear RD TB
  end.
Local Ltac tab_tchar c := tab_load tab_tchar_bytes TABB_TCHAR TAB_IS_TOKEN_CHAR len_TCHAR c 0x156ea.
Local Ltac tab_qd c := tab_load tab_qd_bytes TABB_QD TAB_IS_QDCHAR len_QD c 0x15f57.
Local Ltac tab_qp c := tab_load tab_qp_bytes TABB_QP TAB_IS_QPCHAR len_QP c 0x15e57.

