(* [comment removed for export] *)
Local Ltac chx_dispatch IH p xv CTX PURE HC XS :=
  let K59 := fresh "K59" in let K61 := fresh "K61" in let KB := fresh "KB" in let KL2 := fresh "KL2" in
  step; if_cases K59; zify_cond K59;
  [ to_cut IH 2%nat p xv CTX PURE |];
  step; if_cases K61; zify_cond K61;
  [ (* [comment removed for export] *)
    step; if_cases KB; zify_cond KB;
    [ eapply chx_exit_clean; [exact CTX | exact PURE | lia]
    | eapply chx_exit_bbad; [exact CTX | exact PURE | lia] ]
  | (* [comment removed for export] *)
    step; store_it HC XS; rebuild_ctx CTX;
    step; if_cases KL2; zify_cond KL2; rewrite ?unsigned_lit in KL2 by lia;
    [ eapply chx_exit_bnm; [exact CTX | exact PURE | lia]
    | step; replace (p + 2) with (p + 1 + 1) by lia; to_cut IH 6%nat (p + 1) xv CTX PURE ] ].

